-- Generated by scripts/generate-seed-sql.ts from supabase/seed/data/*.json
-- Seeds the real 60-service catalog extracted verbatim from the legacy prototype.

on conflict (id) do update set name = excluded.name, name_bn = excluded.name_bn, sort_order = excluded.sort_order;

on conflict (id) do update set category_id = excluded.category_id, title = excluded.title, title_bn = excluded.title_bn, base_usd = excluded.base_usd, base_bdt = excluded.base_bdt, days = excluded.days, revisions = excluded.revisions, pricing_status = excluded.pricing_status;

on conflict (id) do update set label = excluded.label, unit_price_usd = excluded.unit_price_usd, unit_price_bdt = excluded.unit_price_bdt;

on conflict (service_id, add_on_id) do nothing;
